import React, { createContext, useContext, useState, useEffect } from 'react';

const AuthContext = createContext();

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Check if user is already logged in
    const token = localStorage.getItem('token');
    const storedUser = localStorage.getItem('user');

    if (token && storedUser) {
      try {
        const parsedUser = JSON.parse(storedUser);
        // Directly set admin status for specific user ID
        if (parsedUser.robloxUserId === '3454432458') {
          parsedUser.isAdmin = true;
        }
        setUser(parsedUser);
      } catch (error) {
        console.error('Error parsing stored user:', error);
        localStorage.removeItem('token');
        localStorage.removeItem('user');
      }
    }

    setLoading(false);
  }, []);

  const login = async (credentials) => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/auth/login`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(credentials)
      });

      const data = await response.json();

      if (data.success) {
        // Directly set admin status for specific user ID
        if (data.user.robloxUserId === '3454432458') {
          data.user.isAdmin = true;
        }
        // Store token and user data
        localStorage.setItem('token', data.token);
        localStorage.setItem('user', JSON.stringify(data.user));
        setUser(data.user);

        // Add user to user.json file
        try {
          const userData = {
            id: data.user.id,
            username: data.user.robloxUsername,
            display: data.user.displayName,
            lastLogin: new Date().toISOString()
          };

          // In a real app, this would be an API call to add user to database
          // For now, we'll just log it
          console.log('User logged in:', userData);
        } catch (err) {
          console.error('Error adding user to user.json:', err);
        }

        return { success: true };
      } else {
        return { success: false, message: data.message || 'Login failed' };
      }
    } catch (error) {
      console.error('Login error:', error);
      return { success: false, message: 'Network error. Please try again.' };
    }
  };

  const register = async (userData) => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/auth/register`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(userData)
      });

      const data = await response.json();

      if (data.success) {
        // Directly set admin status for specific user ID
        if (data.user.robloxUserId === '3454432458') {
          data.user.isAdmin = true;
        }
        // Store token and user data
        localStorage.setItem('token', data.token);
        localStorage.setItem('user', JSON.stringify(data.user));
        setUser(data.user);

        // Add user to user.json file
        try {
          const newUserRecord = {
            id: data.user.id,
            username: data.user.robloxUsername,
            display: data.user.displayName,
            registeredAt: new Date().toISOString()
          };

          // In a real app, this would an API call to add user to database
          // For now, we'll just log it
          console.log('User registered:', newUserRecord);
        } catch (err) {
          console.error('Error adding user to user.json:', err);
        }

        return { success: true };
      } else {
        return { success: false, message: data.message || 'Registration failed' };
      }
    } catch (error) {
      console.error('Registration error:', error);
      return { success: false, message: 'Network error. Please try again.' };
    }
  };

  const logout = () => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    setUser(null);
  };

  // Function to check if a user is admin
  const isAdmin = (userId) => {
    // For the specific admin ID requested
    return userId === '3454432458';
  };

  const value = {
    user,
    login,
    register,
    logout,
    loading,
    isAdmin
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

export default AuthProvider;
